function validate([nums, k]) {
  if (nums.length < 1 || nums.length > 200000) return 'nums needs 1 to 2 * 10^5 values.';
  if (k < 1 || k > nums.length) return 'k is between 1 and nums.length.';
  if (nums.some(v => v < -1e9 || v > 1e9)) return 'Each value is between -10^9 and 10^9.';
  return null;
}

