function maxSubarraySum(nums, k) {
  const minPrefix = new Array(k).fill(Infinity);
  minPrefix[0] = 0;
  let prefix = 0;
  let best = -Infinity;
  for (let i = 1; i <= nums.length; i++) {
    prefix += nums[i - 1];
    const slot = i % k;
    best = Math.max(best, prefix - minPrefix[slot]);
    minPrefix[slot] = Math.min(minPrefix[slot], prefix);
  }
  return best;
}

