function maxSubarraySum(nums, k) {
  // Add up every subarray from each start, keeping the lengths that are multiples of k.
  let best = null;
  for (let start = 0; start < nums.length; start++) {
    let sum = 0;
    for (let end = start; end < nums.length; end++) {
      sum += nums[end];
      if ((end - start + 1) % k === 0 && (best === null || sum > best)) best = sum;
    }
  }
  return best;
}

