function generate(rand, size) {
  const pick = (n) => Math.floor(rand() * n);
  const large = size === 'large';
  const n = large ? 2000 : 1 + pick(10);
  const k = 1 + (large && rand() < 0.5 ? pick(20) : pick(n));
  const span = large ? 1e9 : [1, 5, 100, 1e9][pick(4)];
  // A random shift makes some inputs mostly negative and others mostly positive.
  const shift = Math.floor((rand() - 0.5) * span);
  const nums = Array.from({ length: n }, () => Math.max(-1e9, Math.min(1e9, shift + pick(2 * span + 1) - span)));
  return [nums, k];
}
